{
  "permissions": {
    "allow": [
      "Bash(spacectl stack run list:*)",
      "Bash(gh pr checks:*)",
      "Bash(spacectl stack task:*)",
      "WebFetch(domain:docs.spacelift.io)",
      "WebFetch(domain:registry.terraform.io)"
    ],
    "defaultMode": "plan"
  },
  "model": "fable",
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "if echo \"$CLAUDE_TOOL_INPUT\" | grep -qE '(--no-gpg-sign|--no-verify)'; then echo 'BLOCK: Unsigned commits are not allowed' >&2; exit 1; fi"
          }
        ]
      },
      {
        "matcher": "Read",
        "hooks": [
          {
            "type": "command",
            "command": "/Users/kevinbarnard/.claude/hooks/sonar-secrets/build-scripts/pretool-secrets.sh",
            "timeout": 60
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "matcher": "*",
        "hooks": [
          {
            "type": "command",
            "command": "/Users/kevinbarnard/.claude/hooks/sonar-secrets/build-scripts/prompt-secrets.sh",
            "timeout": 60
          }
        ]
      }
    ]
  },
  "statusLine": {
    "type": "command",
    "command": "npx -y ccstatusline@latest",
    "padding": 0
  },
  "enabledPlugins": {
    "playwright@claude-plugins-official": true,
    "clangd-lsp@claude-plugins-official": true,
    "claude-code-setup@claude-plugins-official": true,
    "claude-md-management@claude-plugins-official": true,
    "rust-analyzer-lsp@claude-plugins-official": true,
    "feature-dev@claude-plugins-official": true,
    "superpowers@claude-plugins-official": true,
    "github@claude-plugins-official": true,
    "security-guidance@claude-plugins-official": true,
    "commit-commands@claude-plugins-official": true,
    "sonarqube@claude-plugins-official": true
  },
  "effortLevel": "xhigh",
  "tui": "fullscreen",
  "skipWorkflowUsageWarning": true
}

{
  "permissions": {
    "allow": [
      "Bash(ls -la /Users/kevinbarnard/src/learn/minix/minix/servers/vfs/*.c)",
      "Bash(ls -la /Users/kevinbarnard/src/learn/minix/minix/servers/rs/*.c)",
      "Bash(ls -la /Users/kevinbarnard/src/learn/minix/minix/servers/vm/*.c)",
      "Bash(ls:*)",
      "Read(//Users/kevinbarnard/src/learn/minix/minix/**)",
      "Bash(wc -l kernel/proc.c kernel/proc.h kernel/priv.h kernel/system.c kernel/table.c kernel/clock.c kernel/interrupt.c include/minix/ipc.h include/minix/ipcconst.h include/minix/com.h include/minix/callnr.h)",
      "Bash(gh pr *)",
      "mcp__github__get_pull_request",
      "mcp__github__get_pull_request_files",
      "WebSearch"
    ]
  }
}

